'use strict';
const $=id=>document.getElementById(id),M=WorkshopModel,A=WorkshopAssist,KEY='factoryTools.calculator.v1';
let data=null,targets=[{id:'Desc_IronPlateReinforced_C',rate:10}],inputs=[],calculation=null,resolvedTargets=[];
function element(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e;}
const number=value=>new Intl.NumberFormat(FactoryI18n.locale,{maximumFractionDigits:2}).format(value);
function message(text,error=false){$('message').textContent=text;$('message').hidden=!text;$('message').classList.toggle('error',error);}
function persist(){try{localStorage.setItem(KEY,JSON.stringify({targets,inputs,mode:$('calcMode').value,size:Number($('calcFormat').value)}));}catch{message('Le navigateur ne conserve pas ce calcul. Vous pouvez encore ouvrir sa proposition dans l’atelier.',true);}}
function fields(){const holder=$('targets');holder.replaceChildren();targets.forEach((target,i)=>{const row=element('div',undefined,'target-row'),label=element('label','Produit '+(i+1)),select=element('select');select.id='product-'+i;label.htmlFor=select.id;for(const id of [...new Set(Object.keys(data.productionDefaults||{}).length?Object.keys(data.productionDefaults):Object.values(data.recipes).map(r=>r.outputs[0].id))].sort((a,b)=>data.names[a].localeCompare(data.names[b],'fr'))){const option=element('option',data.names[id]);option.value=id;select.append(option);}select.value=target.id;select.onchange=()=>{target.id=select.value;solve();};const rates=element('div',undefined,'rate-row'),rateLabel=element('label',$('calcMode').value==='input'?'Proportion de sortie':'Débit souhaité'),rate=element('input');rate.type='number';rate.min='.01';rate.max='100000';rate.step='.01';rate.value=target.rate;rate.id='rate-'+i;rate.required=true;rateLabel.htmlFor=rate.id;rateLabel.append(rate);rate.oninput=()=>{target.rate=Number(rate.value);solve();};rates.append(rateLabel,element('span',$('calcMode').value==='input'?'parts':data.itemUnits?.[target.id]==='m³'?'m³ / min':'/ min'));if(targets.length>1){const remove=element('button','×','remove-target');remove.type='button';remove.setAttribute('aria-label','Retirer le produit '+(i+1));remove.onclick=()=>{targets.splice(i,1);fields();solve();};rates.append(remove);}row.append(label,select);if($('calcMode').value!=='input'||targets.length>1)row.append(rates);holder.append(row);});}
function flowRows(holder,rows){holder.replaceChildren();for(const row of rows){const e=element('div',data.names[row.id]||row.id,'flow-item'),rate=element('strong',number(row.rate)+' ');rate.append(element('small',data.itemUnits?.[row.id]==='m³'?'m³ / min':'/ min'));e.append(rate);holder.append(e);}}
function solve(){
 calculation=null;$('toWorkshop').disabled=true;
 try{
  if(!data)throw new Error('Catalogue en cours de chargement.');
  if(!targets.length||targets.some(t=>!data.names[t.id]||!Number.isFinite(t.rate)||t.rate<=0||t.rate>100000)||new Set(targets.map(t=>t.id)).size!==targets.length)throw new Error('Choisissez des produits distincts et un débit positif pour chacun.');
  const fixedInputs=$('calcMode').value==='output'?[]:inputs,resolution=A.resolveObjectives($('calcMode').value,fixedInputs,targets,data);resolvedTargets=resolution.outputs;
  const demand=A.demand({inputs:fixedInputs,outputs:resolvedTargets},data),required=[...demand.requirements].map(([id,rate])=>({id,rate}));calculation={required};
  flowRows($('requirements'),required);flowRows($('outputs'),resolvedTargets);
  const body=$('machines');body.replaceChildren();let machineCount=0,power=0,variablePower=false;
  for(const [item,cycles]of [...demand.work].reverse()){
   const r=demand.byOutput.get(item),load=cycles*r.seconds/60,full=Math.floor(load+1e-9),fraction=Math.max(0,load-full),count=full+(fraction>1e-8?1:0),spec=data.power[r.type];machineCount+=count;
   if(spec?.variable)variablePower=true;if(spec)power+=spec.mw*(full+Math.pow(fraction,spec.exponent));
   const cadence=fraction>1e-8?(full?full+' à 100 % · ':'')+'1 à '+number(fraction*100)+' %':'100 % chacune',row=element('tr');
   for(const value of [r.name,data.machineNames?.[r.type]||M.TYPES[r.type]?.name||r.type,String(count),cadence])row.append(element('td',value));body.append(row);
  }
  $('machineCount').textContent=machineCount+' machines';$('powerInfo').textContent=number(power)+' MW théoriques'+(variablePower?' + consommation variable de certaines machines':'');$('placementInfo').textContent='Chaîne complète depuis les ressources brutes. Sous-produits calculés sans recyclage automatique.';
  $('result').hidden=false;$('resultEmpty').hidden=true;const layoutIssue=A.layoutLimit({inputs:fixedInputs,outputs:resolvedTargets},data);$('toWorkshop').disabled=!!layoutIssue;$('toWorkshop').title=layoutIssue||'';if($('layoutLimit')){$('layoutLimit').textContent=layoutIssue||'';$('layoutLimit').hidden=!layoutIssue;}const byproducts=$('byproducts');if(byproducts){byproducts.replaceChildren();if(demand.surplus.length){flowRows(byproducts,demand.surplus);byproducts.prepend(element('h3','Sous-produits à récupérer ou évacuer'));}}
  $('external').href='https://satisfactory-calculator.com/fr/planners/production/index/json/'+encodeURIComponent(JSON.stringify(Object.assign(Object.fromEntries(resolvedTargets.map(t=>[t.id,String(t.rate)])),fixedInputs.length?{input:Object.fromEntries(inputs.map(r=>[r.id,String(r.rate)]))}:{})));
  $('clearInputs').hidden=true;$('importedInputs').hidden=true;
  message($('calcMode').value==='input'?'Maximum théorique pour les entrées choisies.':$('calcMode').value==='both'&&resolution.scale<1?'Sorties ajustées aux entrées disponibles : '+number(resolution.scale*100)+' % de l’objectif.':'');persist();
 }catch(error){$('result').hidden=true;$('resultEmpty').hidden=false;$('resultEmpty').textContent='Ajustez les produits ou les débits pour calculer votre recette.';$('machineCount').textContent='';message(error.message,true);}
}
$('clearInputs').onclick=()=>{inputs=[];solve();};
$('targetsForm').addEventListener('submit',e=>{e.preventDefault();solve();});$('calcFormat').onchange=solve;
$('addTarget').onclick=()=>{if(!data)return;const r=Object.values(data.recipes).find(r=>!targets.some(t=>t.id===r.outputs[0].id));if(!r)return;targets.push({id:r.outputs[0].id,rate:10});fields();solve();};
$('linkForm').onsubmit=e=>{e.preventDefault();try{if(!data)throw new Error('Catalogue en cours de chargement.');const flows=A.parseCalculator($('source').value);if(!flows.outputs.length)throw new Error('Ce lien ne contient aucune sortie cible.');for(const t of flows.outputs)if(!(Object.hasOwn(data.productionDefaults||{},t.id)||Object.values(data.recipes).some(r=>r.outputs[0].id===t.id)))throw new Error('Ce produit n’est pas encore pris en charge : '+(data.names[t.id]||t.id));targets=flows.outputs;inputs=flows.inputs;$('calcMode').value=inputs.length?'both':'output';fields();inputFields();solve();if(calculation)message('Lien récupéré : '+targets.map(t=>data.names[t.id]+' · '+number(t.rate)+'/min').join(', ')+'. Les recettes standard ont été recalculées localement.');}catch(error){message(error instanceof SyntaxError?'Le lien ne contient pas des objectifs lisibles. Copiez son adresse complète depuis le calculateur.':error.message,true);}};
$('toWorkshop').onclick=()=>{if(!calculation)return;try{const layout=A.calculate({inputs:$('calcMode').value==='output'?[]:inputs,outputs:resolvedTargets},data,{size:Number($('calcFormat').value)}),project=M.fresh(crypto.randomUUID());project.size=Number($('calcFormat').value);project.name=(resolvedTargets.map(t=>data.names[t.id]).join(' + ')+' — '+resolvedTargets.map(t=>number(t.rate)).join(' + ')+'/min').slice(0,80);project.objects=M.clone([...layout.objects,...layout.logistics]);project.floors=M.clone(layout.floors);project.structure=M.clone(layout.structure);project.links=M.clone(layout.links);project.flows={inputs:M.clone($('calcMode').value!=='output'?inputs:calculation.required),outputs:M.clone(resolvedTargets)};sessionStorage.setItem('factoryTools.calculator.pending',JSON.stringify(M.read(project)));location.href='/atelier';}catch(error){message('Impossible d’ouvrir la proposition : '+error.message,true);}};
fetch('/planner-data.json').then(r=>{if(!r.ok)throw new Error('Catalogue indisponible.');return r.json();}).then(result=>{data=result;try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved){const flows=A.parseCalculator(JSON.stringify(Object.assign({input:Object.fromEntries(saved.inputs.map(r=>[r.id,r.rate]))},Object.fromEntries(saved.targets.map(r=>[r.id,r.rate])))));if(M.FORMATS.includes(saved.size)&&flows.outputs.every(t=>(Object.hasOwn(data.productionDefaults||{},t.id)||Object.values(data.recipes).some(r=>r.outputs[0].id===t.id)))){targets=flows.outputs;inputs=flows.inputs;$('calcFormat').value=saved.size;$('calcMode').value=['input','both','output'].includes(saved.mode)?saved.mode:inputs.length?'both':'output';}}}catch{}fields();inputFields();solve();}).catch(error=>message(error.message,true));

function inputFields(){const mode=$('calcMode').value;$('inputEditor').hidden=mode==='output';$('modeHelp').textContent=mode==='input'?'Choisissez les sorties à maximiser. Avec plusieurs sorties, les proportions sont conservées (ex. 1 plaque pour 2 barres).':mode==='both'?'Les sorties sont des plafonds. Si les entrées manquent, elles sont réduites dans la même proportion.':'Indiquez les débits de sortie souhaités ; les entrées seront calculées.';const holder=$('inputRows');holder.replaceChildren();inputs.forEach((input,i)=>{const row=element('div',undefined,'target-row'),label=element('label','Entrée '+(i+1)),select=element('select');select.id='input-item-'+i;label.htmlFor=select.id;for(const [id,name]of Object.entries(data.names)){const option=element('option',name);option.value=id;select.append(option);}select.value=input.id;select.onchange=()=>{input.id=select.value;solve();};const rateLabel=element('label',data.itemUnits?.[input.id]==='m³'?'Débit disponible m³ / min':'Débit disponible / min'),rate=element('input');rate.type='number';rate.min='.01';rate.step='.01';rate.value=input.rate;rate.oninput=()=>{input.rate=Number(rate.value);solve();};rateLabel.append(rate);const remove=element('button','Retirer','remove-target');remove.type='button';remove.onclick=()=>{inputs.splice(i,1);inputFields();solve();};row.append(label,select,rateLabel,remove);holder.append(row);});}
$('calcMode').onchange=()=>{if($('calcMode').value!=='output'&&!inputs.length)inputs=[{id:'Desc_OreIron_C',rate:120}];fields();inputFields();solve();};
$('addInput').onclick=()=>{const id=[...Object.keys(data.names).filter(id=>id.startsWith('Desc_Ore')),...Object.keys(data.names)].find(id=>!inputs.some(i=>i.id===id)&&!targets.some(t=>t.id===id));if(id){inputs.push({id,rate:120});inputFields();solve();}};
